    template<class T> static int operator()(T*) { return 1; }
    template<class T> int operator()(T) const { return 2; }
};
int main() { int x=0; return F()(&x)!=1 || F()(x)!=2; }

int other(int) { return 9; }
struct F {
    static int operator()(int x) { return x+1; }
    using P=int(*)(int);
    operator P() const { return other; }
};
int main() { return F()(4)!=5; }

